const root = ReactDOM.createRoot(document.getElementById('root'));

// --- New Auto-Update Logic ---
const checkForUpdates = () => {
  console.log('Cordova,checkForUpdates');

  if (cordova.plugins && cordova.plugins.InAppUpdate) {
    console.log("Cordova, checking for Play Store updates...");
    
    cordova.plugins.InAppUpdate.getUpdateAvailability((result) => {
      // result will be 'UPDATE_AVAILABLE' if there is a newer version on Play Store
      console.log('Cordova,result',result);

      if (result === 'UPDATE_AVAILABLE') {
        console.log("Cordova, update found! Triggering immediate update.");
        
        // .updateImmediate() forces a full-screen update UI
        // .updateFlexible() allows the user to use the app while downloading in background

        cordova.plugins.InAppUpdate.updateImmediate(
          () => console.log("Update success"),
          (err) => console.error("Update failed", err)
        );
      } else {
        console.log("Cordova, app is up to date.");
      }
    }, (err) => {
      console.error("Cordova, update check failed", err);
    });
  }else{
    console.log("Cordova, else..");
  }
};

// Render React DOM
const renderReactDom = async () => {
  root.render(
  <Provider store={store}>
      <Main />
  </Provider>
);
  document.documentElement.classList.remove("booting"); // body goes back to normal
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", "#ffffff");

};

const registerServiceWorker = async () =>{
  console.log("Cordova,registerServiceWorker");
  if('serviceWorker' in navigator){
    console.log('Cordova,service worker is available')
    navigator.serviceWorker.register('/sw.js')
    .then(function(){
      console.log('Cordova,service worker registered')
    });
  }
}

