// Cordova Initialization
const initCordova = () => {
  renderReactDom();

  document.addEventListener(
    'deviceready',
    () => {
      console.log('Cordova is ready');

      // 1. Check for Auto-Updates immediately
      checkForUpdates();

      // 2. Persist storage check
      if (!window.indexedDB) {
        console.log("IndexedDB is not supported in this environment.");
      } else {
        console.log("IndexedDB is supported.");
        navigator.storage.persist().then((isPersisted) => {
          console.log(isPersisted ? "Storage will persist" : "Storage may be cleared by the OS");
        });
      }

      if (window.cordova && /android/i.test(navigator.userAgent)) {
        document.documentElement.classList.add("android-app");
      }

      // Request location permission
      requestLocationPermission();
      // setTimeout(() => {
      //   navigator?.splashscreen?.hide();
      // }, 1000);
    },
    false
  );
};

// Main Initialization
